(7157737, 1097534, 152252, '<td valign="top">Amazing shadow and textures. Great capture! Top 3</td>', 'Amazing shadow and textures. Great capture! Top 3', '2014-01-15 02:37:24.000000', NULL, 1),
(7157742, 1097107, 152252, '<td valign="top">That expression is priceless. Great capture.</td>', 'That expression is priceless. Great capture.', '2014-01-15 02:38:34.000000', NULL, 1),
(7157911, 1097606, 174283, '<td valign="top">I can feel the energy</td>', 'I can feel the energy', '2014-01-15 12:43:52.000000', NULL, 1),
(7158192, 1097241, 173844, '<td valign="top">Riveting image as this person makes his/her glacial way across the wide street amid the garish colors and bustle of modernity.  The reflections are pivotal and beautifully captured.  Seems so alone.</td>', 'Riveting image as this person makes his/her glacial way across the wide street amid the garish colors and bustle of modernity.  The reflections are pivotal and beautifully captured.  Seems so alone.', '2014-01-16 00:27:43.000000', NULL, 1),
(7158195, 1097534, 173844, '<td valign="top">Beautiful interplay of light and dark, this person coming down a narrow street, furthered narrowed by shadows, seems to be threading a needle.  That detail is still visible in the shadowed areas is a further treat.</td>', 'Beautiful interplay of light and dark, this person coming down a narrow street, furthered narrowed by shadows, seems to be threading a needle.  That detail is still visible in the shadowed areas is a further treat.', '2014-01-16 00:34:12.000000', NULL, 1),
(7158197, 1097772, 173844, '<td valign="top">Very engaging black and white that captures a child being a child.  I''m assuming that she''s going through the puddle just to go through the puddle.  I like how the world goes on around her, but she''s in a world of her own.</td>', 'Very engaging black and white that captures a child being a child.  I''m assuming that she''s going through the puddle just to go through the puddle.  I like how the world goes on around her, but she''s in a world of her own.', '2014-01-16 00:39:33.000000', NULL, 1),
(7158199, 1097753, 173844, '<td valign="top">Beautifully picks out a moment of simple engagement.  Depth of focus is perfect.</td>', 'Beautifully picks out a moment of simple engagement.  Depth of focus is perfect.', '2014-01-16 00:42:03.000000', NULL, 1),
(7158202, 1097757, 173844, '<td valign="top">Great splashes of color against the muted background.  Enjoyable photo.</td>', 'Great splashes of color against the muted background.  Enjoyable photo.', '2014-01-16 00:45:13.000000', NULL, 1),
(7158206, 1097699, 173844, '<td valign="top">Intriguing almost silhouettes, well-framed and given mystery by the hand in the background.  Is that not a pipe?</td>', 'Intriguing almost silhouettes, well-framed and given mystery by the hand in the background.  Is that not a pipe?', '2014-01-16 00:50:24.000000', NULL, 1),
(7158208, 1097606, 173844, '<td valign="top">The warmth of these people here brings a smile to my face. Well-framed.</td>', 'The warmth of these people here brings a smile to my face. Well-framed.', '2014-01-16 00:53:37.000000', NULL, 1),
